window.__votdWeek && window.__votdWeek({"week":"2029-06-18","reading":"Doctrine and Covenants 64–66","days":[{"d":"2029-06-18","ref":"D&C 64:10","b":"D&C","c":64,"v":10,"he":"אֲנִי יְהוָה אֶסְלַח לַאֲשֶׁר אֶסְלָח אַךְ מִכֶּם נִדְרָשׁ לִסְלֹחַ לְכׇל אָדָם׃","en":"I, the Lord, will forgive whom I will forgive, but of you it is required to forgive all men."},{"d":"2029-06-19","ref":"D&C 64:11","b":"D&C","c":64,"v":11,"he":"וַאֲמַרְתֶּם בִּלְבַבְכֶם יִשְׁפֹּט אֱלֹהִים בֵּינִי וּבֵינֶךָ וְיִגְמׇלְךָ כְּמַעֲשֶׂיךָ׃","en":"And ye ought to say in your hearts—let God judge between me and thee, and reward thee according to thy deeds."},{"d":"2029-06-20","ref":"D&C 64:34","b":"D&C","c":64,"v":34,"he":"הִנֵּה יְהוָה דּוֹרֵשׁ הַלֵּב וְנֶפֶשׁ חֲפֵצָה וְהַחָפֵץ וְהַשּׁוֹמֵעַ יֹאכַל טוּב אֶרֶץ צִיּוֹן בְּאַחֲרִית הַיָּמִים הָאֵלֶּה׃","en":"Behold, the Lord requireth the heart and a willing mind; and the willing and obedient shall eat the good of the land of Zion in these last days."},{"d":"2029-06-21","ref":"D&C 65:4","b":"D&C","c":65,"v":4,"he":"הִתְפַּלְּלוּ אֶל יְהוָה קִרְאוּ בְּשֵׁם קׇדְשׁוֹ הוֹדִיעוּ נִפְלְאוֹתָיו בָּעַמִּים׃","en":"Pray unto the Lord, call upon his holy name, make known his wonderful works among the people."},{"d":"2029-06-22","ref":"D&C 66:5","b":"D&C","c":66,"v":5,"he":"הִנֵּה אָמֵן אֲנִי אֹמֵר לְךָ רְצוֹנִי כִּי תַּכְרִיז בְּשׂוֹרָתִי מֵאֶרֶץ לְאֶרֶץ וּמֵעִיר לְעִיר אָכֵן בַּגְּלִילוֹת סָבִיב אֲשֶׁר לֹא הֻכְרְזָה׃","en":"Behold, verily I say unto you, that it is my will that you should proclaim my gospel from land to land, and from city to city, yea, in those regions round about where it has not been proclaimed."},{"d":"2029-06-23","ref":"D&C 66:11","b":"D&C","c":66,"v":11,"he":"שְׁמֹר הָאֲמָרִים הָאֵלֶּה כִּי אֱמֶת וְנֶאֱמָנִים הֵם וְתַאְדִּיר מִשְׂרָתְךָ וְתִנְגַּח עַמִּים רַבִּים לְצִיּוֹן בְּשִׁירֵי שִׂמְחַת עוֹלָם עַל רֹאשָׁם׃","en":"Keep these sayings, for they are true and faithful; and thou shalt magnify thine office, and push many people to Zion with songs of everlasting joy upon their heads."},{"d":"2029-06-24","ref":"D&C 66:12","b":"D&C","c":66,"v":12,"he":"עֲמֹד בַּדְּבָרִים הָאֵלֶּה עַד הַקֵּץ וִיהִי־לְךָ עֲטֶרֶת חַיֵּי עוֹלָם לִימִין אָבִי הַמָּלֵא חֶסֶד וֶאֱמֶת׃","en":"Continue in these things even unto the end, and you shall have a crown of eternal life at the right hand of my Father, who is full of grace and truth."}]});
